#include "../../SRC/Server/GameServer/raid/icc/LichKing.hpp"
#include <iostream>
#include <stdexcept>
using namespace EclipseRaid::ICC;
void Require(bool b,const char* s){if(!b)throw std::runtime_error(s);}
struct World:LichKingPort{Difficulty mode;std::vector<unsigned> phases;std::vector<uint32_t> spells;unsigned wins=0;Difficulty Mode()const override{return mode;}void Ability(uint32_t s)override{spells.push_back(s);}void Phase(unsigned p)override{phases.push_back(p);}void Victory()override{wins++;}};
int main(){for(auto mode:{Difficulty::Normal10,Difficulty::Normal25,Difficulty::Heroic10,Difficulty::Heroic25}){World w;w.mode=mode;LichKing c(91);c.Reset(w);for(unsigned i=0;i<160;i++)c.Tick(w,250);Require(std::count(w.spells.begin(),w.spells.end(),70372)==1,"first horror at15 seconds");Require(std::count(w.spells.begin(),w.spells.end(),70337)==1,"necrotic plague in phase1");c.Health(w,70);Require(c.Phase()==2,"70 percent begins first winter");c.Health(w,1);Require(c.Phase()==2,"cannot skip transition by health");for(unsigned i=0;i<260;i++)c.Tick(w,250);Require(c.Phase()==3,"first winter ends after62.5 seconds");for(unsigned i=0;i<180;i++)c.Tick(w,250);Require(std::find(w.spells.begin(),w.spells.end(),69037)!=w.spells.end(),"phase2 valkyr carriers");c.Health(w,40);Require(c.Phase()==4,"40 percent second winter");for(unsigned i=0;i<260;i++)c.Tick(w,250);Require(c.Phase()==5,"second winter opens final combat phase");for(unsigned i=0;i<64;i++)c.Tick(w,250);Require(std::find(w.spells.begin(),w.spells.end(),Heroic(mode)?73654:68980)!=w.spells.end(),"mode-specific soul harvest");if(Heroic(mode)){Require(c.Phase()==6,"heroic group soul phase");for(unsigned i=0;i<224;i++)c.Tick(w,250);Require(c.Phase()==5,"heroic realm returns to fight");}c.Health(w,10);Require(c.Ending()&&!w.wins,"10 percent scripted finale cannot skip");for(unsigned i=0;i<140;i++)c.Tick(w,250);Require(w.wins==1,"finale awards victory once");}
 std::cout<<"ICC_LICH_KING_PASS phases winters valkyr soul_modes scripted_finale four_modes\n";
}
